  "heroglyph.flow.dogCharacter.slideLabel": "SLIDE",
  "heroglyph.flow.dogCharacter.slideAriaLabel": "Další charakter",
  "heroglyph.flow.dogCharacter.slide.guardian.title": "Strážce (Oko Doga)",
  "heroglyph.flow.dogCharacter.slide.player.title": "Hráč (Okřídlený míč)",
  "heroglyph.flow.dogCharacter.slide.energizer.title": "Hyperaktiv (Plná baterie)",
  "heroglyph.flow.dogCharacter.slide.maverick.title": "Rebel (Pirátský znak)",
  "heroglyph.flow.dogCharacter.slide.waterlover.title": "Vodomil (Vlny)",
  "heroglyph.flow.dogCharacter.slide.gourmet.title": "Gurmán (Nekonečná miska)",
  "heroglyph.flow.dogCharacter.slide.lover.title": "Mazlík (Amor)",
  "heroglyph.flow.dogCharacter.slide.chiller.title": "Pohodář (Pohovka)",
  "heroglyph.flow.dogCharacter.slide.guardian.desc": "Hlídá dveře, jako by to byla brána do posmrtného života. Nejdřív štěká, otázky nikdy.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "Duši vymění za další hod míčem. Největší radost: oblíbená hračka.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "Žádný vypínač. Žádné baterie. Nejčastější otázka: jaké drogy ten pes bere?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "Novodobý pirát s vlastním světem a vlastními pravidly. Selektivní sluch je jeho první zákon.",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "Existují dva druhy psů — a jeden se dá zaměnit za rybu. Mokrá srst: 100 % štěstí.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "Žrádlo je mise. Plné nasazení, nula váhání — a sní i to, co ty ne.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "Cizí člověk pro něj neexistuje. Pošťáka vítá jako dávno ztraceného spřízněnce. Pokaždé.",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "Ovládl prastaré umění nedělat absolutně nic — a krásně.",
