  "entry.title": "In Dog I Trust",
  "entry.subtitle": "Tohle není vtip. Každé vážně míněné náboženství musí tyhle věci prohlásit.",
  "entry.criteria.theology.title": "Teologie",
  "entry.criteria.theology.body": "Nejlepší přítel, ochránce, učitel, parťák v každém dobrodružství. Pes dává lásku bez podmínek — a když jdeme po jeho boku, stáváme se lidštějšími.",
  "entry.criteria.canon.title": "Kánon",
  "entry.criteria.canon.body": "Každá víra má své písmo. To naše je DOGMA: naše pouto se psem sepsané do dvanácti kapitol, volně k přečtení na dogma.dogypt.com.",
  "entry.criteria.community.title": "Komunita",
  "entry.criteria.community.body": "Jsme pejskaři s posláním. Každý sám dokáže změnit málo — společně nemá naše síla hranic.",
  "entry.criteria.symbol.title": "Symbol",
  "entry.criteria.symbol.body": "Každá víra má svůj znak. Ten náš je heroglyph: jedinečné posvátné znamení pro každého psa, srozumitelné v každém jazyce, kdekoli.",
  "entry.criteria.ritual.title": "Rituál",
  "entry.criteria.ritual.body": "Procházka. Každodenní terapie, která udržuje tělo i mysl v kondici — a duši taky. Nejstarší rituál, který už teď dodržujeme, aniž by nám to někdo musel říkat.",
  "entry.criteria.vision.title": "Vize",
  "entry.criteria.vision.body": "Pozvednout pouto mezi člověkem a psem — a bojovat za respekt a lepší život, který každý pes zaslouží.",
  "entry.criteria.offerings.title": "Oběť",
  "entry.criteria.offerings.note": "(symbolická pocta)",
  "entry.criteria.offerings.pill": "€11 · jednorázově",
  "entry.criteria.offerings.tag": "100% transparentnost",
  "entry.criteria.offerings.body": "€11, jednou. Symbolická oběť — každý příjem i každý výdaj v účetnictví otevřeném všem. Energie, která nás drží při životě.",
  "entry.criteria.legitimacy.title": "Legitimita",
  "entry.criteria.legitimacy.pill": "zbývá {count} členů",
  "entry.criteria.legitimacy.body": "Tisíc zakladatelů a jsme dost silní, abychom se zaregistrovali jako národ, který musí zákon uznat. Poslední znamení — dosáhnout na něj můžeš jen ty.",
