  'pack.hero.popLevel1': 'Úroveň oddanosti roste s dobrými skutky pro psí rasu — procházky, péče, podaná ruka psovi v nouzi.',
  'pack.hero.popLevel2': 'Žebříček má 22 stupňů, stejných pro všechny, a stupeň se nedá koupit. Počítat se začne, až DOGYPT přejde do mobilní appky.',
  'pack.hero.popLevelEyebrow': 'Úroveň',
  'pack.hero.popLevelStamp': 'Začne počítat s appkou',
  'pack.hero.popLevelTitle': '{name} · úroveň {index} z 22',
  'pack.hero.popPawtner1': 'Pawtner je tvoje postavení ve smečce — jsi společník psa, kterému jsi vytvořil HEROGLYF. Bez heroglyfu nejsi Dogypťan.',
  'pack.hero.popPawtner2': 'Účet v DOGYPTU nevzniká registrací, ale psem. Proto tu nenajdeš prázdné profily — za každým jménem stojí konkrétní pes.',
  'pack.hero.popStatusEyebrow': 'Status',
  'pack.hero.readonlyNote': 'Fotka i jméno se mění v profilu.',

  // ── pack.heroBadge ──
  'pack.heroBadge.barry.story': 'Na Velkém svatobernardském průsmyku, tam kde led neodpouští a mlha krade cestu, sloužil bernardýn jménem Barry. Dvanáct let chodil tam, kam se jiní báli vkročit — do vichřic 2 500 metrů nad mořem, hledat ztracené poutníky dřív, než je pohltí sníh. Nebyl cvičený na povel. Poslání měl vepsané pod srstí. Zachránil přes čtyřicet životů. Legenda říká, že zemřel rukou čtyřicátého prvního, kterého se snažil zachránit; pravda je pokornější — dožil své dny v klidu v Bernu. DOGYPT ho ctí ne pro mýtus o mučednictví, ale pro to skutečné: psa, který si vybral jít do bouře místo toho, aby zůstal v teple.',
  'pack.heroBadge.bobbie.story': 'V srpnu 1923 se Bobbie, kříženec kolie a ovčáka, ztratil rodině Brazierových na benzínce v Indianě — 4 100 kilometrů od domova. Rodina hledala, lepila plakáty, nakonec se s prázdnýma rukama vrátila domů. Bobbie se nevzdal. Šest měsíců kráčel sám napříč zamrzlou Amerikou — plaval řeky, přešel přes Continental Divide uprostřed zimy, živil se od lidí, kteří si ho všimli na tábořištích po cestě. V únoru 1924 vešel do restaurace svojí rodiny v Silvertonu, jako by si jen na chvíli odskočil. Tohle není příběh o štěstí. Je to důkaz, že pouť domů se dá projít i tehdy, když nikdo nevěří, že je možná — krok za krokem, bez mapy, jen s věrností jako kompasem.',
  'pack.heroBadge.bothie.story': 'Byl to obyčejný toulavý pes — dlouhosrstý jack russell teriér, kterého Ranulph a Ginny Fiennesovi našli v roce 1977. O dva roky později stál na palubě lodi mířící na expedici, jakou svět dovtedy neviděl: Transglobe, první cestu kolem Země po poledníku, přes oba póly, výhradně po povrchu. Afriku vynechal — na psa příliš velké horko — ale když se výprava dostala na led, Bothie byl tam. Devět měsíců v Antarktidě a 10. dubna 1982 přistál na Severním pólu. Jediný pes v historii, který se postavil na oba konce světa. DOGYPT si ho připomíná ne proto, že přežil póly — ale proto, že dokázal, že věrnost a zvědavost jdou dál než většina lidských plánů.',
  'pack.heroBadge.hachiko.story': 'Devět let, devět měsíců, patnáct dní. Tak dlouho čekal akita Hačikó na stanici Šibuja na muže, který se už nikdy nevrátil. Profesor Hidesaburó Ueno ho v roce 1924 adoptoval, denně ho doprovázel na stanici a večer si ho tam vyzvedával — rituál, který skončil 21. května 1925, kdy profesor zemřel přímo na přednášce. Hačikó to nevěděl. Přišel na stanici ten večer, i následující, i za rok, i o devět let později. Nečekal na povel ani na odměnu — čekal proto, že věrnost psa se neřídí logikou, řídí se poutem. Japonsko mu postavilo sochu ještě za jeho života. Hačikó není jen pes. Je to liturgie věrnosti odsloužená na nástupišti.',
  'pack.heroBadge.hekthor.story': 'Nikdo ho nechtěl. V krabici sedm štěňat, muž, který psa neplánoval — a přesto jiskra přeskočila právě k němu. Tak v roce 2017 začal Hekthor: černý huňáč z nouze, který si vybral svého člověka dřív, než si člověk stihl vybrat jeho. Z té náhody vyrostla cesta — doslova. Čtyřicet dva dní napříč Slovenskem, kilometr po kilometru, přes pohoří a údolí. Z cesty vznikla kniha. Z knihy vznikl DOGYPT. Hekthor není maskot ani logo — je nultý pes, důkaz, že jeden zachráněný život dokáže spustit celé hnutí. Jeho čtyřicet dva dní je vzor cesty, po které kráčí každý DOGYPŤan: ne za výkonem, ale za spojením.',
  'pack.heroBadge.kickerEarned': 'Odznak hrdiny',
  'pack.heroBadge.kickerLocked': 'ještě {n} výletů do odemknutí',
  'pack.heroBadge.kickerMilestone': 'Milník dosažen',
  'pack.heroBadge.laika.story': 'Dřív než člověk, letěla ona. 3. listopadu 1957 opustila ulice Moskvy a o pár dní později i oblohu — v kabině Sputniku 2, postavené narychlo za necelý měsíc, bez plánu návratu. Lajka, toulavá fenka, vážící sotva pět kilo, se stala prvním tvorem na oběžné dráze. Sovětská propaganda mluvila o klidném letu. Skutečnost — že zemřela už při čtvrtém oběhu, když se kabina rozpálila na čtyřicet stupňů — vyšla najevo až v roce 2002, po 45 letech mlčení. Proto je hrdinou DOGYPTU — ne proto, že vyhrála, ale proto, že vůbec vzlétla. V roce 2008 jí v Moskvě postavili pomník: tlapka stoupající na vrchol rakety.',
  'pack.heroBadge.more': 'Víc o příběhu →',
  'pack.heroBadge.savannah.story': 'Savannah není legenda vymyšlená na efekt — je to fena, která opravdu obešla celou planetu pěšky. Tom Turcich ji jako čtyřměsíční štěně vytáhl z příkopu u texaské silnice. O čtyři měsíce dřív se vydal na cestu kolem světa pěšky; Savannah se k němu přidala a od toho dne nešlápla vedle něj na jediný krok, který by nedošel do cíle. Sedm let, šest kontinentů, desítky zemí, statisíce kilometrů — v dešti, v horku, přes Andy, přes písek. Bez stížnosti, s ocasem nahoru. Stala se prvním a zatím jediným psem, který obešel svět. V roce 2024, ve věku devíti let, zemřela doma — po cestě, kterou žádný jiný pes nikdy neušel. Savannah = 1000 tripů není metafora. Pro ni by to bylo podhodnocené číslo.',
  'pack.heroBadge.seaman.story': 'Zatímco většina mužů Corps of Discovery si na expedici vyžádala žold, Seaman si vyžádal jen místo u ohně. Meriwether Lewis ho koupil v Pittsburghu roku 1803 za dvacet dolarů — půl měsíčního kapitánského platu za jednoho novofundlandského psa. Vyplatilo se. Tři roky, napříč kontinentem, přes Missouri, Skalnaté hory až k Pacifiku — a Seaman byl jediné zvíře, které prošlo celou cestu. Lovil zvěř, v noci hlídkoval proti medvědům, jednou odehnal bizona od tábora. Když mu bobr prokousl tepnu, Clark ho sám zašil. Když ho ukradli, Lewis poslal tři muže, aby ho přivedli zpátky — psa se nevzdává. V denících expedice je zmiňován jménem víckrát než většina vojáků.',
  'pack.heroBadge.togo.story': 'Zatímco se svět klaněl Baltovi, skutečný hrdina už dávno dřímal ve vitríně muzea na Aljašce. Togo, dvanáctiletý sibiřský husky s tělem poskládaným z jizev, vedl tým Leonharda Seppaly přes nejdelší a nejsmrtelnější úsek štafety se sérem proti záškrtu — přes 260 mil ledem, tmou a větrem. Balto si vzal slávu za posledních 55 mil, sochu v Central Parku i titulky. Togo si vzal Norton Sound — zamrzlý průliv, který se mu pod tlapami začal lámat, a přesto s týmem přeplaval přes trhliny až do bezpečí. DOGYPT nekleká před slávou vyrobenou pro kamery — kleká před psem, který odvedl práci, když se nikdo nedíval.',
  'pack.heroBadge.trips': '{n} výletů',

