  // ── pack.network ──
  'pack.network.ads.body': 'Placená reklama je velmi neefektivní způsob, jak získat nové pejskaře — a vyhazování našich peněz velkým korporacím. Mnohem lepší je odměňovat za aktivitu přímo členy hnutí. Má to jeden háček: <strong style="font-weight:600">opravdu účinné to bude jen tehdy, když půjdeš do akce a řekneš o nás svému okolí</strong> :)',
  'pack.network.ads.header': 'Proč tenhle způsob?',
  'pack.network.ads.wordAd': 'reklama',
  'pack.network.ads.wordScroll': 'cizí člověk si scrolluje dál',
  'pack.network.allBones': 'Všechno {n}',
  'pack.network.back': 'Zpět',
  'pack.network.bonesLabel': 'Tvoje BONES',
  'pack.network.bonesRate': '{n} BONES = 1 €',
  'pack.network.bonesUnit': 'bones',
  'pack.network.capHintLog': 'Strop 1:1 — dar dokáže vyrovnat jen to, co jsi už odžil.',
  'pack.network.capHintRow': 'Strop 1:1 — dar vyrovnává to, co jsi odžil',
  'pack.network.capped.none': 'Z tohohle převodu žádná oddanost — tvoje dary už vyrovnávají všechno, co jsi odžil. BONES i tak projdou. <i>Peníze zdvojnásobí roky, nikdy je nenahradí.</i>',
  'pack.network.capped.room': 'Strop na <b style="color:#2a1608">{room}</b> — dar dokáže vyrovnat jen to, co jsi už odžil ({lived} oddanosti zatím). BONES i tak projdou; čest čeká na dny.',
  'pack.network.chainFirstInvite': 'tvoje první pozvání',
  'pack.network.chainJoined': '{n} se přidalo',
  'pack.network.chainWhoever': 'kohokoliv přivedou',
  'pack.network.chainYou': 'ty',
  'pack.network.close': 'Zavřít',
  'pack.network.confirmSend': 'Jsi si jistý? Po odeslání BONES opustí tvůj zůstatek — tohle se nedá vrátit.',
  'pack.network.copyLinkAria': 'Zkopírovat zvací odkaz',
  'pack.network.devotionWord': 'oddanost',
  'pack.network.emptyLine': 'Zatím nikdo — první jméno tady je začátek tvojí linie.',
  'pack.network.eyebrow': 'DOGYPT roste díky tobě',
  'pack.network.generatingLink': 'Generujeme tvůj odkaz…',
  'pack.network.groupDirect': 'přímo',
  'pack.network.groupTheirBrings': 'jejich pozvání',
  'pack.network.info.bones.body': 'BONES je vnitřní měna DOGYPT — hravé jméno pro reálnou věc. Pes platí kostmi; my taky. <b>Vyděláváš</b> je tím, že přivádíš pejskaře do smečky a posouváš hnutí vpřed, a <b>utratíš</b> je uvnitř DOGYPT: podporou sbírek pro útulky, získáním merche a později platbou ostatním Dogyptianům za to, co tvoří. <b>{n} BONES = 1 €.</b>',
  'pack.network.info.bones.cap': 'Co jsou BONES?',
  'pack.network.info.why.body': 'Hnutí téhle velikosti se nedá koupit — žádný rozpočet neosloví cizího člověka tak, jak jeden Dogyptian osloví přítele. Proto smečka dává odměnu tam, kde je dosah — k tobě. Když se někdo přidá přes tvůj odkaz, dostaneš <b>{l1} BONES</b>; když přivede dalšího, dostaneš ještě <b>{l2}</b>. Každý Dogyptian, který šíří slovo, není prodejce — je misionář, a téhle práce si vážíme.',
  'pack.network.info.why.cap': 'Proč tě žádáme',
  'pack.network.inLine': 'V tvojí linii',
  'pack.network.intro': 'Hnutí roste jen tehdy, když členové šíří jeho poselství a přivedou nové členy. Proto tě žádáme přímo: <strong style="color:#2a1608;font-weight:600">pozvi pejskaře, které znáš</strong>. Tady přesně je, jak to funguje.',
  'pack.network.inviteLinkHeader': 'Tvůj zvací odkaz',
  'pack.network.linkFailed': 'Zvací odkaz se nepodařilo načíst.',
  'pack.network.linkRetry': 'Zkusit znovu',
  'pack.network.listSummary': '{n} lidí · {b} BONES získaných',
