  'pack.nature.balance.body': 'Konstituce tvého psa je daná na celý život, ale může se vychýlit z rovnováhy. Zaškrtni cokoliv, co platí — kolik chceš nebo i nic.',
  'pack.nature.balance.deficiency': 'příliš málo',
  'pack.nature.balance.excess': 'příliš mnoho',
  'pack.nature.balance.none': 'Nic ze seznamu? Nech to prázdné a pokračuj — to je ta nejlepší odpověď, jaká existuje.',
  'pack.nature.balance.reading': 'Podle tradiční čínské medicíny se tohle čte jako',
  'pack.nature.balance.signs': 'Co jsi zaškrtl',
  'pack.nature.balance.support': 'Elementy, o které je tady třeba se opřít, jsou',
  'pack.nature.balance.supportBelow': 'Odkud začít, je hned níž — je to sklon, ne předpis.',
  'pack.nature.balance.supportHow': 'Jejich výživa výš je odkud začít — je to sklon, ne předpis.',
  'pack.nature.balance.title': 'Děje se právě teď něco?',
  'pack.nature.balance.vet': 'Tohle patří k veterináři',
  'pack.nature.balance.vetNote': 'Co jsi zaškrtl tady, patří k veterináři, ne k misce. Pořád nám to říká, na kterou stranu se rovnováha naklání — ale diagnóza není nic, k čemu by radila strava.',
  'pack.nature.doc.avoid': 'Co proti němu pracuje',
  'pack.nature.doc.details': 'Detaily, které pomáhají',
  'pack.nature.doc.detailsFrom': 'drobnosti, které nejsou zřejmé',
  'pack.nature.doc.duty': 'Co ta práce vyžaduje ode dne',
  'pack.nature.doc.food': 'Co mu svědčí',
  'pack.nature.doc.footTitle': 'KDO JE TVŮJ PES',
  'pack.nature.doc.i.sub': 'Z čeho je udělaný — tělo, miska a roční období. Podle tradiční čínské medicíny.',
  'pack.nature.doc.i.title': 'Konstituce',
  'pack.nature.doc.ib.sub': 'Co jsi zaškrtl, přečtené tak, jak to čte čínská medicína',
  'pack.nature.doc.ib.title': 'Kam se rovnováha naklání',
  'pack.nature.doc.ii.sub': 'Co pro smečku drží — a kolik práce a odpočinku to znamená',
  'pack.nature.doc.ii.title': 'Role ve smečce',
  'pack.nature.doc.iii.sub': 'Stojí NAD základní rolí — není jí sokem',
  'pack.nature.doc.iii.title': 'Zvláštní role',
  'pack.nature.doc.iv.sub': 'Podstata je výš — tady zůstává to, co se uhádnout nedá',
